import json
import re
from docx import Document

TEMPLATE = '/root/offer_letter_template.docx'
DATA_PATH = '/root/employee_data.json'
OUTPUT = '/root/offer_letter_filled.docx'

with open(DATA_PATH, 'r') as f:
    data = json.load(f)

# Normalize for string replacement
str_data = {k: ('' if v is None else str(v)) for k, v in data.items()}

include_relocation = str_data.get('RELOCATION_PACKAGE','').strip().lower() == 'yes'

start_marker = '{{IF_RELOCATION}}'
end_marker = '{{END_IF_RELOCATION}}'

pattern = re.compile(r'\{\{([A-Z0-9_]+)\}\}')

def set_paragraph_text(para, new_text):
    runs = para.runs
    if runs:
        runs[0].text = new_text
        for r in runs[1:]:
            r.text = ''


def replace_placeholders_in_text(text):
    def repl(match):
        key = match.group(1)
        return str_data.get(key, match.group(0))
    return pattern.sub(repl, text)


def process_paragraph(para):
    text = para.text
    if not text:
        return

    if start_marker in text and end_marker in text:
        if include_relocation:
            new_text = text.replace(start_marker, '').replace(end_marker, '')
            new_text = replace_placeholders_in_text(new_text)
        else:
            new_text = ''
        if para.runs:
            set_paragraph_text(para, new_text)
        return

    # Standard placeholder replacement
    if pattern.search(text):
        new_text = replace_placeholders_in_text(text)
        if new_text != text:
            set_paragraph_text(para, new_text)


def process_table(table):
    for row in table.rows:
        for cell in row.cells:
            for para in cell.paragraphs:
                process_paragraph(para)
            for nested in cell.tables:
                process_table(nested)


doc = Document(TEMPLATE)

for para in doc.paragraphs:
    process_paragraph(para)

for table in doc.tables:
    process_table(table)

for section in doc.sections:
    for para in section.header.paragraphs:
        process_paragraph(para)
    for para in section.footer.paragraphs:
        process_paragraph(para)

# If relocation excluded, remove any empty paragraphs created by conditional removal
# Keep formatting simple: leave as blank if present; Word will render minimal spacing.

doc.save(OUTPUT)

print('Wrote', OUTPUT)
